<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,nextTick} from 'vue'
defineProps<{title:string;busy:boolean;error:string}>();const emit=defineEmits<{close:[];confirm:[]}>(),panel=ref<HTMLElement>();let previous:HTMLElement|null=null
function key(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();emit('close')}if(e.key==='Tab'){const items=Array.from(panel.value?.querySelectorAll<HTMLButtonElement>('button:not([disabled])')||[]);if(!items.length){e.preventDefault();return}if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0]?.focus()}}}
onMounted(()=>{previous=document.activeElement as HTMLElement;void nextTick(()=>panel.value?.querySelector('button')?.focus());document.addEventListener('keydown',key,true)});onBeforeUnmount(()=>{document.removeEventListener('keydown',key,true);if(previous?.isConnected)previous.focus()})
</script>
<template><Teleport to="body"><div class="modal-scrim" @click.self="!busy&&emit('close')"><section ref="panel" class="upload-dialog" role="alertdialog" aria-modal="true" aria-labelledby="delete-conversation-title" aria-describedby="delete-conversation-description"><h2 id="delete-conversation-title">删除这段对话？</h2><p>{{title}}</p><p id="delete-conversation-description">对话将移至最近删除。研究空间中的论文、PDF、独立笔记和成果不会因此删除。正在生成的回复将停止。</p><p v-if="error" role="alert" class="form-error">{{error}}</p><div class="button-row"><button class="secondary-button" :disabled="busy" @click="emit('close')">取消</button><button class="secondary-button history-danger" :disabled="busy" @click="emit('confirm')">{{busy?'正在处理…':'移至最近删除'}}</button></div></section></div></Teleport></template>
<style>.history-danger{color:#a83d57!important}</style>
